/**
 * Catálogo real de peças e projetos padrão, extraído das OS de estrutura, das atas de reunião
 * (planilhas) e dos detalhamentos TTK/Norte (modulação Q30) dos eventos de 2026:
 * Eco Run SP, Circuito das Estações Campinas, Blue Run RJ, Longevidade Bradesco (Campinas e
 * Salvador), Desafio Energia Petrobras Bike SP, Santander Night Run Campo Grande, Bravus Race RJ
 * e Circuito BB Natal — e das 193 OS de estrutura de 2026 da pasta SharePoint
 * "1- ATA E O.S EVENTOS 2026" (Calendário), consolidadas por nome e lista de peças em set/2026:
 * projetos que aparecem nas OS entram com descrição e, quando a lista varia pouco entre eventos,
 * a variação vira outro projeto com a diferença no título.
 *
 * Importado por `npm run importar:catalogo` (idempotente: peças por código, projetos por nome;
 * projeto existente cuja lista mudou ganha nova versão, desde que a versão atual seja do importador).
 */
import type { Setor } from "../../src/server/db/schema";

export type PecaCatalogo = {
  codigo: string;
  nome: string;
  setor: Setor;
  familia: string;
  unidade?: string;
  estoque?: number;
  permiteEmProjeto?: boolean;
  descricao?: string;
  /** false = não aparece nas listas de seleção das solicitações (marcenaria, por enquanto). */
  disponivelEmSolicitacoes?: boolean;
};

export type ProjetoCatalogo = {
  nome: string;
  /** Nomes com que o projeto já foi importado antes: o importador acha por eles e renomeia. */
  nomesAnteriores?: string[];
  categoria: string;
  descricao: string | null;
  /** false = não aparece nas listas de seleção das solicitações (marcenaria, por enquanto). */
  disponivelEmSolicitacoes?: boolean;
  /** [código da peça, quantidade por projeto] */
  itens: Array<[string, number]>;
  /** Arquivos em scripts/dados/imagens (renders e modulações TTK), anexados ao projeto na importação. */
  imagens?: string[];
};

const E = "ESTRUTURA" as const;
